type Intent = 'looking_for_club' | 'need_player';
type PlatformId = 'ps5' | 'xbox' | 'pc' | 'switch2';
type CommunityPlayer = {
  id: string; userId: string; handle: string; display: string; position: string; secondary: string; level: number; ovr: number | null;
  archetype: string; platform: PlatformId; division: string; region: string; languages: string[];
  tags: string[]; availability: string; intent: Intent; portrait: number; club?: string; avatarUri: string | null;
  eaId: string; gamertag: string; levelVerified: boolean;
};

const PLATFORMS: (PlatformId|'all')[] = ['all','ps5','xbox','pc','switch2'];
const PLATFORM_LABEL: Record<PlatformId,string> = {ps5:'פלייסטיישן 5',xbox:'Xbox Series X|S',pc:'מחשב (PC)',switch2:'נינטנדו סוויץ׳ 2'};
const POSITIONS = ['ALL','GK','LB','CB','RB','CDM','CM','LM','RM','CAM','LW','RW','ST'];
const POSITION_LABEL: Record<string,string> = {
  ALL:'כל העמדות', GK:'שוער', LB:'מגן שמאלי', CB:'בלם', RB:'מגן ימני',
  CDM:'קשר אחורי', CM:'קשר מרכזי', LM:'קשר שמאלי', RM:'קשר ימני',
  CAM:'קשר התקפי', LW:'כנף שמאלי', RW:'כנף ימני', ST:'חלוץ',
};
const POSITION_ALIASES: Record<string,string[]> = {
  GK:['GK','שוער'], LB:['LB','מגן שמאלי','Left Back'], CB:['CB','בלם','Center Back','Centre Back'],
  RB:['RB','מגן ימני','Right Back'], CDM:['CDM','קשר הגנתי','קשר אחורי','Defensive Midfielder'],
  CM:['CM','קשר מרכזי','Central Midfielder'], LM:['LM','קשר שמאלי','Left Midfielder'],
  RM:['RM','קשר ימני','Right Midfielder'], CAM:['CAM','קשר התקפי','Attacking Midfielder'],
  LW:['LW','כנף שמאלי','Left Winger'], RW:['RW','כנף ימני','Right Winger'], ST:['ST','חלוץ','Striker'],
};
function positionMatches(value:string, selected:string) {
  if (selected === 'ALL') return true;
  const raw = (value || '').trim();
  if (!raw) return false;
  if (raw === 'מגן') return selected === 'LB' || selected === 'RB';
  if (raw === 'כנף') return selected === 'LW' || selected === 'RW';
  if (raw === 'קשר') return ['CDM','CM','LM','RM','CAM'].includes(selected);
  const aliases = POSITION_ALIASES[selected] ?? [selected];
  return aliases.some(alias => alias.toLocaleLowerCase() === raw.toLocaleLowerCase());
}
const INK='#F4F7F2', MUTED='#A6B3AE', LIME='#C9F56A', AQUA='#76D9C2', PANEL='#101817';
function levelColor(level:number){
  if(level>=50)return '#F0C979';
  if(level>=40)return '#C9A7FF';
  if(level>=30)return '#8ABFFF';
  if(level>=20)return LIME;
  if(level>=10)return '#91C9F3';
  if(level>=5)return AQUA;
  return '#E7EEE6';
}
function levelStage(level:number){
  if(level>=50)return 'רמת שיא';
  if(level>=40)return 'מומחה';
  if(level>=30)return 'מתקדם';
  if(level>=20)return 'ותיק';
  if(level>=10)return 'מיומן';
  if(level>=5)return 'בדרך למעלה';
  return 'מתחיל';
}

function Eyebrow({children}:{children:string}){return <View style={s.eyebrow}><View style={s.dot}/><Text style={s.eyebrowText}>{children}</Text></View>;}
function Chip({label,active,onPress}:{label:string;active:boolean;onPress:()=>void}){return <Pressable onPress={onPress} accessibilityRole="button" style={({pressed})=>[s.chip,active&&s.chipActive,pressed&&{opacity:0.84}]}><Text style={[s.chipText,active&&s.chipTextActive]}>{label}</Text></Pressable>;}
function Tag({children,tone='plain'}:{children:string;tone?:'plain'|'lime'}){return <View style={[s.tag,tone==='lime'&&s.tagLime]}><Text style={[s.tagText,tone==='lime'&&{color:LIME}]}>{children}</Text></View>;}
function Action({label,icon,onPress,secondary=false}:{label:string;icon:keyof typeof Ionicons.glyphMap;onPress:()=>void;secondary?:boolean}){return <Pressable onPress={onPress} accessibilityRole="button" style={({pressed})=>[s.action,secondary&&s.actionSecondary,pressed&&{opacity:0.85,transform:[{translateY:1}]}]}><Ionicons name={icon} size={18} color={secondary?INK:'#071216'}/><Text style={[s.actionText,secondary&&{color:INK}]}>{label}</Text></Pressable>;}
function QuickTile({title,subtitle,icon,onPress}:{title:string;subtitle:string;icon:keyof typeof Ionicons.glyphMap;onPress:()=>void}){return <Pressable onPress={onPress} accessibilityRole="button" style={({pressed})=>[s.quickAction,pressed&&{opacity:0.86,transform:[{translateY:1}]}]}><View style={s.quickIcon}><Ionicons name={icon} size={21} color={LIME}/></View><View style={s.quickCopy}><Text style={s.quickTitle}>{title}</Text><Text style={s.quickSub}>{subtitle}</Text></View><Ionicons name="chevron-forward" size={17} color="#A9BEC9"/></Pressable>;}

function ArchetypeLevelPanel({level,verified}:{level:number;verified:boolean}) {
  const tint=levelColor(level);
  const next=level<50?level+1:null;
  return <View style={s.levelPanel}>
    <View style={s.levelPanelHeader}>
      <View style={{flex:1,gap:4}}>
        <Text style={s.levelPanelKicker}>CLUBS · ARCHETYPE PROGRESSION</Text>
        <Text style={s.levelPanelTitle}>רמת הארכיטיפ</Text>
      </View>
      <View style={[s.levelProofBadge,{borderColor:verified?'rgba(201,245,106,0.4)':'rgba(180,198,186,0.18)'}]}>
        <Ionicons name={verified?'shield-checkmark-outline':'information-circle-outline'} size={14} color={verified?LIME:'#A9BAAF'}/>
        <Text style={[s.levelProofText,verified&&{color:LIME}]}>{verified?'נבדקה':'דיווח עצמי'}</Text>
      </View>
    </View>
    <View style={s.levelChain}>
      <View style={[s.levelNode,s.levelNodeCurrent,{borderColor:tint,shadowColor:tint}]}>
        <Text style={s.levelNodeCaption}>הרמה שלך</Text>
        <Text style={[s.levelNodeNumber,{color:tint}]}>{level}</Text>
        <Text style={s.levelNodeFoot}>LEVEL</Text>
        <View style={[s.levelNodeAccent,{backgroundColor:tint}]}/>
        <Text style={[s.levelNodeStage,{color:tint}]}>{levelStage(level)}</Text>
      </View>
      <View style={s.levelConnector}>
        <View style={s.axpCapsule}><Ionicons name="flash-outline" size={14} color={tint}/><Text style={[s.axpText,{color:tint}]}>AXP</Text></View>
        <View style={s.levelConnectorLine}><View style={s.levelConnectorCore}/><View style={s.levelConnectorNode}/></View>
        <Text style={s.levelConnectorCaption}>ניסיון</Text>
        <Text style={s.levelConnectorMissing}>לא נמסר</Text>
      </View>
      <View style={[s.levelNode,s.levelNodeNext,{borderColor:next?'rgba(190,210,199,0.2)':'rgba(240,201,121,0.55)'}]}>
        <Text style={s.levelNodeCaption}>{next?'השלב הבא':'הושלם'}</Text>
        <Text style={[s.levelNodeNumber,s.levelNodeNextNumber,!next&&{color:'#F0C979'}]}>{next??50}</Text>
        <Text style={s.levelNodeFoot}>{next?'NEXT LEVEL':'LEVEL CAP'}</Text>
        <View style={s.levelNodeAccentNext}/>
        <View style={s.levelNodeLock}>{next?<Ionicons name="lock-closed-outline" size={14} color="#87998D"/>:<Ionicons name="checkmark-circle-outline" size={15} color="#F0C979"/>}</View>
      </View>
    </View>
    <View style={s.levelPanelFooter}>
      <Text style={s.levelPanelHint}>רמת הארכיטיפ מוצגת לפי הפרופיל שפורסם. נתוני AXP יוצגו רק כאשר יימסר ערך אמיתי.</Text>
    </View>
  </View>;
}

function PlayStylesPlaceholder() {
  return <View style={s.playStylesPanel}>
    <View style={s.playStylesHeader}>
      <View style={s.playStylesMark}><Ionicons name="sparkles-outline" size={18} color={LIME}/></View>
      <View style={{flex:1,gap:3}}>
        <Text style={s.playStylesTitle}>PlayStyles · סגנונות משחק</Text>
        <Text style={s.playStylesCopy}>יופיעו כאן לאחר שיוזנו בפרופיל השחקן.</Text>
      </View>
    </View>
    <View style={s.playStylesSlots}>
      {[0,1,2,3,4].map(n=><View key={n} style={s.playStylesSlot}><Ionicons name="add" size={17} color="#6C8073"/></View>)}
    </View>
  </View>;
}

function ProCard({player,onPress,onContact}:{player:CommunityPlayer;onPress:()=>void;onContact:()=>void}) {
  const tint=levelColor(player.level);
  return <View style={s.playerCard}>
    <Pressable onPress={onPress} accessibilityRole="button" style={s.cardVisual}>
      {player.avatarUri ? <Image source={{uri:player.avatarUri}} style={{width:'100%',height:'100%'}} resizeMode="cover"/> : <View style={s.cardNoImage}><View style={s.cardNoImageGlyph}><Ionicons name="person-outline" size={58} color="#AFC5B2"/></View><Text style={s.cardNoImageText}>לא הועלתה תמונה</Text></View>}<LinearGradient colors={['rgba(3,8,6,0.01)','rgba(3,8,6,0.1)','rgba(3,8,6,0.88)']} locations={[0,0.46,1]} style={StyleSheet.absoluteFill}/>
      <View style={s.cardTop}><View style={s.statusChip}><View style={s.dot}/><Text style={s.statusText}>{player.intent==='need_player'?'מחפשים שחקנים':'פתוח להצעות'}</Text></View><Text style={s.cardCode}>1 CLUB · {player.id.toUpperCase()}</Text></View>
      {player.ovr !== null ? <View style={s.ovrBadge}><Text style={s.ovrLabel}>דירוג אישי</Text><Text style={s.ovrNumber}>{player.ovr}</Text></View> : null}<View style={[s.levelBadge,{borderColor:tint+'66'}]}><Text style={s.levelLabel}>LEVEL · רמה</Text><Text style={[s.levelNumber,{color:tint}]}>{String(player.level).padStart(2,'0')}</Text><Text style={s.levelStage}>{levelStage(player.level)}</Text></View>
      <View style={s.cardCaption}><Text style={s.playerName}>{player.display}</Text><Text style={s.playerHandle}>@{player.handle}</Text></View>
      <View style={s.posBadge}><Text style={s.posMain}>{player.position}</Text>{player.secondary ? <Text style={s.posSub}>{player.secondary}</Text> : null}</View>
    </Pressable>
    <View style={s.cardBody}>
      <View style={s.cardTitleRow}><View style={[s.platformIcon,{borderColor:tint+'5C'}]}><Ionicons name={player.platform==='pc'?'desktop-outline':'game-controller-outline'} size={19} color={tint}/></View><View style={{flex:1,gap:4,alignItems:'flex-end'}}><Text style={s.archetype}>{player.archetype}</Text><Text style={s.cardMeta}>{player.division} · {PLATFORM_LABEL[player.platform]}</Text></View></View>
      {player.tags.length ? <View style={s.tagRow}>{player.tags.map(tag=><Tag key={tag} tone={tag==='רמה מאומתת'?'lime':'plain'}>{tag}</Tag>)}</View> : null}
      <View style={s.infoLine}><Ionicons name="globe-outline" size={15} color={AQUA}/><Text style={s.infoText}>{player.region}</Text></View>
      <View style={s.infoLine}><Ionicons name="layers-outline" size={15} color={AQUA}/><Text style={s.infoText}>{player.division} · {PLATFORM_LABEL[player.platform]}</Text></View>
      <View style={s.cardFooter}><Pressable onPress={onContact} style={s.contactButton}><Ionicons name="chatbubble-ellipses-outline" size={15} color="#11170A"/><Text style={s.contactText}>פנייה לשחקן</Text></Pressable><Pressable onPress={onPress} style={s.moreButton}><Ionicons name="arrow-up-right" size={18} color={INK}/></Pressable></View>
    </View>
  </View>;
}

export default function GroundsPreviewScreen() {
  const app=useApp(),router=useRouter();
  const {width}=useWindowDimensions(),scroll=useRef<ScrollView>(null),intro=useRef(new Animated.Value(0)).current;
  const [intent,setIntent]=useState<'all'|Intent>('all'),[platform,setPlatform]=useState<PlatformId|'all'>('all'),[position,setPosition]=useState('ALL'),[search,setSearch]=useState(''),[notice,setNotice]=useState(''),[selected,setSelected]=useState<CommunityPlayer|null>(null),[infoOpen,setInfoOpen]=useState(false);
  const compact=width<760,columns=width>=1440?5:width>=1280?4:width>=900?3:width>=600?2:1;
  useEffect(()=>{Animated.timing(intro,{toValue:1,duration:760,useNativeDriver:true}).start();},[intro]);
  const players=useMemo<CommunityPlayer[]>(()=>app.grounds.map((post,index)=>{
    const profile=app.profiles.find(item=>item.id===post.userId);
    return {id:post.id,userId:post.userId,handle:post.gamertag||post.eaId||profile?.displayName||'שחקן קהילה',display:profile?.displayName||post.gamertag||post.eaId||'שחקן קהילה',position:post.position,secondary:'',level:post.playerLevel,ovr:post.skillRating,archetype:post.archetype,platform:post.platform,division:post.division==='elite'?'ליגת על':'ליגה '+post.division,region:post.region,languages:[],tags:post.levelVerified?['רמה מאומתת']:[],availability:'',intent:post.intent,portrait:index%6,avatarUri:post.avatarUri??profile?.avatarUrl??null,eaId:post.eaId,gamertag:post.gamertag,levelVerified:post.levelVerified};
  }),[app.grounds,app.profiles]);
  const recruiting=useMemo(()=>players.filter(p=>p.intent==='need_player'),[players]);
  const filtered=useMemo(()=>players.filter(p=>{
    const q=search.trim().toLowerCase();
    if(intent!=='all'&&p.intent!==intent)return false;
    if(platform!=='all'&&p.platform!==platform)return false;
    if(position!=='ALL'&&!positionMatches(p.position,position)&&!positionMatches(p.secondary,position))return false;
    const hay=(p.display+' '+p.handle+' '+p.archetype+' '+p.region+' '+p.position+' '+PLATFORM_LABEL[p.platform]+' '+p.tags.join(' ')).toLowerCase();
    if(q&&!hay.includes(q))return false;
    return true;
  }),[players,intent,platform,position,search]);
  const showNotice=(message:string)=>setNotice(message);

  return <View style={s.page}>
    <StatusBar barStyle="light-content"/><Stack.Screen options={{headerShown:false,title:'The Grounds — Preview'}}/><SiteNav/>
    <ScrollView ref={scroll} style={s.scroll} contentContainerStyle={s.scrollContent} showsVerticalScrollIndicator={false}>
      <View style={s.shell}><Image source={require('@/assets/images/scene-grounds.png')} resizeMode="stretch" style={s.pageBackgroundImage} />
        <View style={s.hero}>
          <Animated.View style={[s.heroContent,{opacity:intro,transform:[{translateY:intro.interpolate({inputRange:[0,1],outputRange:[24,0]})}]}]}>
            <View style={s.heroTop}><Eyebrow>FC 27 · קהילת מועדונים</Eyebrow><View style={s.previewBadge}><Text style={s.previewBadgeText}>הדגמת עיצוב</Text></View></View>
            <View style={[s.heroMain,compact&&{flexDirection:'column',alignItems:'stretch',gap:18}]}>
              <View style={[s.heroCopy,compact&&{maxWidth:'100%',width:'100%',alignItems:'stretch'}]}><Text style={s.heroHebrew}>המגרש שלך. האנשים שלך.</Text><Text style={s.heroLead}>מוצאים שחקנים שמתאימים לסגנון שלך, בונים קבוצה טובה יותר ונכנסים למשחק עם האנשים הנכונים.</Text><View style={[s.heroActions,compact&&{flexDirection:'column',alignItems:'stretch'}]}><Action label="חפש שחקנים" icon="search" onPress={()=>scroll.current?.scrollTo({y:610,animated:true})}/><Action label="פרסם פרופיל" icon="person-add-outline" secondary onPress={()=>router.push('/grounds/new')}/></View></View>
              <View style={[s.heroBrand,compact&&{alignItems:'flex-start'}]}><Text style={s.heroOverline}>FC 27 · קהילת מועדונים</Text><Text style={[s.heroTitle,compact&&{fontSize:46,lineHeight:52,letterSpacing:-0.5}]}>THE <Text style={{color:LIME}}>GROUNDS</Text></Text></View>
            </View>
            <View style={[s.quickActions,compact&&{flexWrap:'wrap'}]}>
              <QuickTile title="חיפוש שחקנים" subtitle="סנן לפי עמדה ופלטפורמה" icon="search" onPress={()=>scroll.current?.scrollTo({y:590,animated:true})}/>
              <QuickTile title="חיפוש קבוצה" subtitle="גלה מודעות גיוס שפורסמו" icon="people" onPress={()=>{setIntent('need_player');scroll.current?.scrollTo({y:590,animated:true});}}/>
              <QuickTile title="פרסום פרופיל" subtitle="תמונה היא רשות" icon="person-add-outline" onPress={()=>router.push('/grounds/new')}/>
              <QuickTile title="אתגרים" subtitle="בקרוב" icon="sparkles-outline" onPress={()=>showNotice('אתגרי הקהילה יתווספו בקרוב.')}/>
            </View>
            
          </Animated.View>
          <View style={s.heroRail}><Text style={s.railText}>נבנה לקהילה</Text><View style={s.railLine}/><Text style={s.railText}>לא שירות רשמי</Text></View>
        </View>
        <View style={s.content}>
          <View style={[s.sectionIntro,compact&&{alignItems:'stretch'}]}><View style={{flex:1,gap:7}}><Eyebrow>רשת השחקנים</Eyebrow><Text style={s.sectionTitle}>מצא את האנשים שלך.</Text><Text style={s.sectionLead}>לא עוד מודעות בלי הקשר. פרופילים ברורים, התאמה לפי המשחק שאתם אוהבים ודרך קלה להתחיל לדבר.</Text></View><Pressable onPress={()=>router.push('/grounds/new')} style={s.outlineAction}><Ionicons name="add" size={17} color={LIME}/><Text style={s.outlineText}>פרסם את פרופיל השחקן שלך</Text></Pressable></View>
          <View style={s.filterPanel}>
            <View style={[s.filterHead,compact&&{flexDirection:'column',alignItems:'stretch'}]}><View style={s.resultRow}><View style={s.dot}/><Text style={s.resultLabel}>שחקנים מהקהילה</Text><Text style={s.demoCount}>{filtered.length} פרופילים</Text></View><View style={s.searchBox}><Ionicons name="search" size={18} color={MUTED}/><TextInput value={search} onChangeText={setSearch} placeholder="חיפוש שם, Build, אזור או סגנון..." placeholderTextColor="#77837D" style={s.searchInput} returnKeyType="search" accessibilityLabel="חיפוש פרופילים"/>{search?<Pressable onPress={()=>setSearch('')}><Ionicons name="close-circle" size={18} color={MUTED}/></Pressable>:null}</View></View>
            <View style={s.tabRow}><Chip label="הכל" active={intent==='all'} onPress={()=>setIntent('all')}/><Chip label="מחפשים קבוצה" active={intent==='looking_for_club'} onPress={()=>setIntent('looking_for_club')}/><Chip label="קבוצות מחפשות שחקנים" active={intent==='need_player'} onPress={()=>setIntent('need_player')}/></View>
            <View style={s.filterGroup}><Text style={s.filterLabel}>עמדה</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.chipScroll}>{POSITIONS.map(item=><Chip key={item} label={POSITION_LABEL[item] ?? item} active={position===item} onPress={()=>setPosition(item)}/>)}</ScrollView></View>
            <View style={s.filterGroup}><Text style={s.filterLabel}>פלטפורמה</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.chipScroll}>{PLATFORMS.map(item=><Chip key={item} label={item==='all'?'כל הפלטפורמות':PLATFORM_LABEL[item]} active={platform===item} onPress={()=>setPlatform(item)}/>)}</ScrollView></View>
          </View>
          <View style={s.cardsHeader}><View style={{gap:4}}><Text style={s.cardsTitle}>שחקנים מומלצים</Text><Text style={s.cardsSubtitle}>פרופילים אמיתיים מתוך מודעות שפורסמו · נתונים שלא נמסרו לא יוצגו</Text></View><View style={s.sortTag}><Ionicons name="options-outline" size={15} color={MUTED}/><Text style={s.sortText}>התאמה</Text></View></View>
          <View style={[s.cardsGrid,compact&&{gap:14}]}>{filtered.map(player=><View key={player.id} style={{width:columns===5?'18.6%':columns===4?'23.6%':columns===3?'31.8%':columns===2?'48.7%':'100%'}}><ProCard player={player} onPress={()=>setSelected(player)} onContact={()=>{if(!app.user){showNotice('צריך להתחבר כדי לפנות לשחקן.');router.push('/register');return;}router.push('/grounds/chat/'+player.userId);}}/></View>)}{!filtered.length?<View style={s.emptyState}><Ionicons name={players.length?'search-outline':'people-outline'} size={30} color={MUTED}/><Text style={s.emptyTitle}>{players.length?'לא נמצאו התאמות':'עדיין אין שחקנים שפרסמו פרופיל'}</Text><Text style={s.emptyText}>{players.length?'נסו לשנות את המסננים או לנקות את החיפוש.':'כאן יופיעו שחקנים רק לאחר פרסום אמיתי. אפשר להיות הראשונים ולפרסם את פרופיל השחקן שלך.'}</Text>{players.length?<Pressable onPress={()=>{setIntent('all');setPlatform('all');setPosition('ALL');setSearch('');}} style={s.resetButton}><Text style={s.resetText}>ניקוי מסננים</Text></Pressable>:<Pressable onPress={()=>router.push('/grounds/new')} style={s.resetButton}><Text style={s.resetText}>פרסום הפרופיל הראשון</Text></Pressable>}</View>:null}</View>
          <View style={[s.dashboardGrid,compact&&{gap:12}]}>
            <View style={s.dashboardPanel}>
              <View style={s.panelHeader}><Text style={s.panelHeading}>מודעות גיוס</Text><Pressable onPress={()=>{setIntent('need_player');scroll.current?.scrollTo({y:590,animated:true});}}><Text style={s.panelViewAll}>כל המודעות ↗</Text></Pressable></View>
              {recruiting.length ? recruiting.slice(0,3).map(post=><Pressable key={post.id} onPress={()=>setSelected(post)} style={s.panelItem}><View style={s.clubEmblem}><Ionicons name="people-outline" size={24} color={LIME}/></View><View style={s.panelText}><Text style={s.panelTitle}>{post.display}</Text><Text style={s.panelSub}>{post.position} · {post.region}</Text><View style={s.panelTags}><Tag>{PLATFORM_LABEL[post.platform]}</Tag><Tag tone={post.levelVerified?'lime':'plain'}>{post.levelVerified?'רמה מאומתת':'דיווח עצמי'}</Tag></View></View><Ionicons name="chevron-back" size={16} color={MUTED}/></Pressable>) : <View style={s.dashboardEmpty}><Ionicons name="users-outline" size={24} color={MUTED}/><Text style={s.emptyTitle}>אין גיוסים פעילים עדיין</Text><Text style={s.emptyText}>כאן יופיעו מודעות אחרי פרסום אמיתי של שחקנים.</Text><Pressable style={s.panelAction} onPress={()=>router.push('/grounds/new')}><Text style={s.panelActionText}>פרסום מודעה</Text></Pressable></View>}
            </View>
            <View style={s.dashboardPanel}>
              <View style={s.panelHeader}><Text style={s.panelHeading}>מועדונים מובילים</Text><Pressable onPress={()=>showNotice('טבלת המועדונים תוצג לאחר שיצטברו נתוני מועדונים אמיתיים.')}><Text style={s.panelViewAll}>טבלה מלאה ↗</Text></Pressable></View>
              <View style={s.dashboardEmpty}><Ionicons name="shield-outline" size={24} color={MUTED}/><Text style={s.emptyTitle}>אין עדיין מועדונים מובילים</Text><Text style={s.emptyText}>הדירוג יוצג לאחר שיהיו נתוני מועדונים אמיתיים.</Text></View>
            </View>
            <View style={s.dashboardPanel}>
              <View style={s.panelHeader}><Text style={s.panelHeading}>האתגרים האחרונים</Text><Text style={s.panelViewAll}>בקרוב</Text></View>
              <View style={s.challengeComingSoon}><View style={s.challengeComingSoonIcon}><Ionicons name="sparkles-outline" size={26} color={LIME}/></View><Text style={s.panelTitle}>אתגרי הקהילה — בקרוב</Text><Text style={s.panelSub}>האתגרים ייפתחו בהמשך, לאחר שתצמח הקהילה.</Text></View>
            </View>
            <View style={s.dashboardPanel}>
              <View style={s.panelHeader}><Text style={s.panelHeading}>הפרופיל שלך</Text><Pressable onPress={()=>setInfoOpen(true)}><Text style={s.panelViewAll}>עריכה ↗</Text></Pressable></View>
              {app.user ? <View style={s.profileSummary}>{app.user.avatarUrl ? <Image source={{uri:app.user.avatarUrl}} style={s.profileAvatarImage} resizeMode="cover"/> : <View style={s.profileAvatarPlaceholder}><Ionicons name="person-circle-outline" size={42} color={LIME}/></View>}<View style={s.profileIdentity}><Text style={s.panelTitle}>{app.user.displayName}</Text><Text style={s.panelSub}>חבר קהילת ONE CLUB</Text><Text style={s.panelSub}>הפרטים שיופיעו כאן יילקחו מהפרופיל שלך.</Text></View></View> : <View style={s.dashboardEmpty}><Ionicons name="person-circle-outline" size={25} color={MUTED}/><Text style={s.emptyTitle}>הפרופיל שלך</Text><Text style={s.emptyText}>התחבר כדי להציג כאן את הפרטים האישיים שלך.</Text><Pressable style={s.panelAction} onPress={()=>router.push('/register')}><Text style={s.panelActionText}>התחברות</Text></Pressable></View>}
              {app.user ? <Pressable style={s.profileEdit} onPress={()=>router.push('/profile')}><Text style={s.profileEditText}>פתיחת הפרופיל שלי</Text><Ionicons name="settings-outline" color="#C8D8CC" size={16}/></Pressable> : null}
            </View>
          </View>
          <View style={[s.bottomCta,compact&&{flexDirection:'column',alignItems:'stretch'}]}><View style={s.ctaGlow}/><View style={{flex:1,gap:8}}><Eyebrow>הקבוצה שלך, בדרך שלך</Eyebrow><Text style={s.ctaTitle}>הקבוצה הבאה שלך מתחילה כאן.</Text><Text style={s.ctaText}>מגדירים את מי שמחפשים, מציגים את מבנה השחקן (Build) ומתחילים להתחבר לאנשים שמתאימים לכם.</Text></View><Action label="בדיקת הפרופיל שלי" icon="person-circle-outline" secondary onPress={()=>setInfoOpen(true)}/></View>
          <View style={s.footer}><Text style={s.footerBrand}>THE GROUNDS <Text style={{color:LIME}}>/</Text> ONE CLUB</Text><Text style={s.footerNote}>תצוגת קונספט קהילתית · אינה קשורה רשמית ליצרנית המשחק</Text></View>
        </View>
      </View>
    </ScrollView>
    <Modal visible={Boolean(selected)} transparent animationType="fade" onRequestClose={()=>setSelected(null)}><Pressable style={s.modalBackdrop} onPress={()=>setSelected(null)}><Pressable style={s.profileModal} onPress={()=>{}}>{selected?<><View style={s.modalImage}>{selected.avatarUri ? <Image source={{uri:selected.avatarUri}} style={{width:'100%',height:'100%'}} resizeMode="cover"/> : <View style={s.modalNoImage}><Ionicons name="person-outline" size={70} color="#AFC5B2"/><Text style={s.cardNoImageText}>לא הועלתה תמונה</Text></View>}</View><View style={s.modalBody}><View style={s.modalNameRow}><View style={{flex:1,gap:4}}><Text style={s.modalHandle}>@{selected.handle}</Text><Text style={s.modalName}>{selected.display}</Text></View><Pressable onPress={()=>setSelected(null)} style={s.modalClose}><Ionicons name="close" size={20} color="#10150A"/></Pressable></View><Text style={s.modalMeta}>{selected.archetype} · {selected.ovr !== null ? 'דירוג אישי '+selected.ovr+' · ' : ''}רמה {selected.level} · {selected.position}</Text>
          <ArchetypeLevelPanel level={selected.level} verified={selected.levelVerified}/>
          <PlayStylesPlaceholder/>
          <View style={s.profileDetailsGrid}>
            <View style={s.profileDetailsCell}><Text style={s.profileDetailLabel}>פלטפורמה</Text><Text style={s.profileDetailValue}>{PLATFORM_LABEL[selected.platform]}</Text></View>
            <View style={s.profileDetailsCell}><Text style={s.profileDetailLabel}>אזור</Text><Text style={s.profileDetailValue}>{selected.region || 'לא צוין'}</Text></View>
            <View style={s.profileDetailsCell}><Text style={s.profileDetailLabel}>שם משתמש</Text><Text style={s.profileDetailValue}>{selected.gamertag || 'לא צוין'}</Text></View>
            <View style={s.profileDetailsCell}><Text style={s.profileDetailLabel}>EA ID</Text><Text style={s.profileDetailValue}>{selected.eaId || 'לא צוין'}</Text></View>
            <View style={s.profileDetailsCell}><Text style={s.profileDetailLabel}>דיוויז׳ן</Text><Text style={s.profileDetailValue}>{selected.division}</Text></View>
            <View style={s.profileDetailsCell}><Text style={s.profileDetailLabel}>סטטוס רמה</Text><Text style={s.profileDetailValue}>{selected.levelVerified ? 'אומתה' : 'דיווח עצמי'}</Text></View>
          </View>
          <Text style={s.modalDescription}>הפרופיל מבוסס על פרטים שפורסמו על ידי השחקן. רמה מאומתת תסומן רק לאחר בדיקה. דירוג אישי אינו מוצג כ־OVR רשמי של EA.</Text><View style={s.modalActions}><Pressable onPress={()=>{const player=selected;setSelected(null);if(!app.user){router.push('/register');return;}if(player)router.push('/grounds/chat/'+player.userId);}} style={s.contactButton}><Ionicons name="chatbubble-ellipses-outline" color="#11170A" size={16}/><Text style={s.contactText}>שליחת הודעה</Text></Pressable><Pressable onPress={()=>setSelected(null)} style={s.dismissButton}><Text style={s.dismissText}>סגירה</Text></Pressable></View></View></>:null}</Pressable></Pressable></Modal>
    <Modal visible={infoOpen} transparent animationType="fade" onRequestClose={()=>setInfoOpen(false)}><View style={s.modalBackdrop}><View style={s.infoModal}><View style={s.modalNameRow}><Text style={s.infoKicker}>איך זה יעבוד</Text><Pressable onPress={()=>setInfoOpen(false)} style={s.modalClose}><Ionicons name="close" size={20} color="#10150A"/></Pressable></View><Text style={s.infoTitle}>פחות טפסים. יותר התאמות.</Text><Text style={s.infoCopy}>הפרופיל יציג נתונים שהשחקן בחר לשתף: ארכיטיפ, רמה, עמדה, פלטפורמה, אזור ותמונה אם בחר להעלות. רמה מאומתת תסומן רק לאחר בדיקה. ONE CLUB היא קהילת שחקנים עצמאית ואינה שירות רשמי של EA.</Text>{['חיפוש לפי פרטים שמשפיעים על התאמה אמיתית','כרטיס שחקן ומבנה Build שקל לשתף','בלי להעמיד פנים שקיים חיבור למשחק או אימות שלא בוצע'].map(item=><View key={item} style={s.infoBullet}><Ionicons name="checkmark-circle" color={LIME} size={18}/><Text style={s.infoBulletText}>{item}</Text></View>)}<Pressable onPress={()=>setInfoOpen(false)} style={s.infoDone}><Text style={s.infoDoneText}>הבנתי</Text></Pressable></View></View></Modal>
    {notice?<Pressable onPress={()=>setNotice('')} style={s.toast}><Ionicons name="information-circle-outline" size={18} color={LIME}/><Text style={s.toastText}>{notice}</Text><Ionicons name="close" size={16} color={MUTED}/></Pressable>:null}
  </View>;
}

